import pandas as pd
import numpy as np

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/caox.csv"

df = pd.read_csv(DATA_FILE)
df.columns = [str(c).strip() for c in df.columns]

temperature_col = next(c for c in df.columns if "Temperature" in c)
weight_col = next(c for c in df.columns if "Weight (%)" in c)
dtg_col = next(c for c in df.columns if "Deriv" in c and "Weight" in c)

def numeric_pairs(x_col, y_col):
    x = pd.to_numeric(df[x_col], errors="coerce")
    y = pd.to_numeric(df[y_col], errors="coerce")
    valid = x.notna() & y.notna()
    return [[round(float(a), 6), round(float(b), 6)] for a, b in zip(x[valid], y[valid])]

weight_data = numeric_pairs(temperature_col, weight_col)
dtg_data = numeric_pairs(temperature_col, dtg_col)

